// AdminServer is the server API for Admin service.
// All implementations must embed UnimplementedAdminServer
// for forward compatibility.
//
// 后台资产服务
type AdminServer interface {
	// 创建APP资产操作币种显示配置
	CreateAssetCoinConfig(context.Context, *CreateAssetCoinConfigReq) (*AssetCoinConfigResp, error)
	// 更新APP资产操作币种显示配置
	UpdateAssetCoinConfig(context.Context, *UpdateAssetCoinConfigReq) (*AssetCoinConfigResp, error)
	// 删除APP资产操作币种显示配置
	DeleteAssetCoinConfig(context.Context, *DeleteAssetCoinConfigReq) (*DeleteAssetCoinConfigResp, error)
	// 查询APP资产操作币种显示配置详情
	GetAssetCoinConfig(context.Context, *GetAssetCoinConfigReq) (*AssetCoinConfigResp, error)
	// 分页查询APP资产操作币种显示配置
	PageAssetCoinConfigs(context.Context, *PageAssetCoinConfigsReq) (*PageAssetCoinConfigsResp, error)
	// 分页查询资产
	PageUserAssets(context.Context, *PageUserAssetsReq) (*PageUserAssetsResp, error)
	// 查询用户资产详情
	GetUserAssetDetail(context.Context, *GetUserAssetDetailReq) (*GetUserAssetDetailResp, error)
	// 分页查询资产流水
	PageAssetFlows(context.Context, *PageAssetFlowsReq) (*PageAssetFlowsResp, error)
	// 分页查询冻结明细
	PageAssetFreezes(context.Context, *PageAssetFreezesReq) (*PageAssetFreezesResp, error)
	// 分页查询锁仓明细
	PageAssetLocks(context.Context, *PageAssetLocksReq) (*PageAssetLocksResp, error)
	// 后台人工加币
	AddAsset(context.Context, *AddAssetReq) (*ManualChangeAssetResp, error)
	// 后台人工减币
	SubAsset(context.Context, *SubAssetReq) (*ManualChangeAssetResp, error)
	// 后台冻结资产
	FreezeAsset(context.Context, *ManualFreezeAssetReq) (*ManualChangeAssetResp, error)
	// 后台解冻资产
	UnfreezeAsset(context.Context, *ManualUnfreezeAssetReq) (*ManualChangeAssetResp, error)
	// 后台锁仓资产
	LockAsset(context.Context, *ManualLockAssetReq) (*ManualChangeAssetResp, error)
	// 后台解锁资产
	UnlockAsset(context.Context, *ManualUnlockAssetReq) (*ManualChangeAssetResp, error)
	// 设置平台账户（保险基金等，不属于任何用户）
	SetPlatformAccount(context.Context, *SetPlatformAccountReq) (*PlatformAccountResp, error)
	// 查询平台账户
	GetPlatformAccount(context.Context, *GetPlatformAccountReq) (*PlatformAccountResp, error)
	// 幂等调整平台账户余额
	AdjustPlatformAccount(context.Context, *AdjustPlatformAccountReq) (*PlatformAccountResp, error)
	mustEmbedUnimplementedAdminServer()
}

